// Fuzzilli integration in V8 consists of:
// 1. FuzzilliExtension class in fuzzilli/fuzzilli.h/.cc
// 2. Coverage tracking in fuzzilli/cov.h/.cc
// 3. Integration with d8 shell for REPRL mode

// FuzzilliExtension provides fuzzer operations:
class FuzzilliExtension : public v8::Extension {
 public:
  explicit FuzzilliExtension(const char* fun_name)
      : v8::Extension("v8/fuzzilli",
                      BuildSource(buffer_, sizeof(buffer_), fun_name)) {}
  v8::Local<v8::FunctionTemplate> GetNativeFunctionTemplate(
      v8::Isolate* isolate, v8::Local<v8::String> name) override;
  static void Fuzzilli(const v8::FunctionCallbackInfo<v8::Value>& info);
};

// Operations supported:
// - FUZZILLI_CRASH: Trigger various crash types for fuzzing
// - FUZZILLI_PRINT: Output to fuzzer communication channel

// Coverage tracking uses shared memory for edge coverage:
#define SHM_SIZE 0x202000
#define MAX_EDGES ((SHM_SIZE - 4) * 8)

struct shmem_data {
  uint32_t num_edges;
  uint32_t feedback_nexus_count;
  uint32_t max_feedback_nexus;
  uint32_t turbofan_flags;
  uint64_t turbofan_optimization_bits;
  FeedbackNexusData feedback_nexus_data[MAX_FEEDBACK_NEXUS];
  unsigned char edges[];
};

// Integration points in V8:
// 1. d8 shell has --fuzzilli-enable-builtins-coverage flag
// 2. d8 shell has --fuzzilli-coverage-statistics flag  
// 3. REPRL (read-eval-print-reset-loop) mode for fuzzing
// 4. Coverage hooks in compiler pipeline and feedback vector
